#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();

function fail(message) {
  console.error(`\n[KOJAC Invoice V1] ERROR: ${message}\n`);
  process.exit(1);
}

function ok(message) {
  console.log(`[KOJAC Invoice V1] ${message}`);
}

function read(rel) {
  const p = path.join(root, rel);
  if (!fs.existsSync(p)) fail(`File tidak ditemukan: ${rel}`);
  return fs.readFileSync(p, 'utf8');
}

function write(rel, content) {
  const p = path.join(root, rel);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, content.replace(/\r\n/g, '\n'), 'utf8');
  ok(`write ${rel}`);
}

function replaceOnce(rel, before, after) {
  const p = path.join(root, rel);
  const content = read(rel);
  if (content.includes(after)) {
    ok(`skip ${rel} (sudah terpasang)`);
    return;
  }
  const count = content.split(before).length - 1;
  if (count !== 1) fail(`Anchor tidak unik/tidak ditemukan di ${rel}. Ditemukan: ${count}`);
  fs.writeFileSync(p, content.replace(before, after), 'utf8');
  ok(`patch ${rel}`);
}

function ensureProjectAudit() {
  const pkg = JSON.parse(read('package.json'));
  if (pkg.name !== 'kojac-lms-v2') fail(`Project bukan kojac-lms-v2 (name=${pkg.name})`);
  if (!pkg.dependencies?.['@supabase/supabase-js']) fail('Dependency @supabase/supabase-js tidak ditemukan.');
  if (!pkg.dependencies?.['react-router-dom']) fail('Dependency react-router-dom tidak ditemukan.');

  const app = read('src/App.tsx');
  const shell = read('src/components/AppShell.tsx');

  const requiredAppAnchors = [
    'ManagementTeachingReportsPage',
    'path="manajemen/laporan-pembelajaran"',
    'path="tugas-saya"',
  ];
  for (const anchor of requiredAppAnchors) {
    if (!app.includes(anchor)) fail(`Actual src/App.tsx tidak cocok. Anchor hilang: ${anchor}`);
  }

  const requiredShellAnchors = [
    'label="Laporan Pembelajaran"',
    'label="Tugas Saya"',
    'MANAJEMEN',
  ];
  for (const anchor of requiredShellAnchors) {
    if (!shell.includes(anchor)) fail(`Actual AppShell.tsx tidak cocok. Anchor hilang: ${anchor}`);
  }

  if (app.includes('HonorSlip') || shell.includes('Slip Honor')) {
    ok('Slip Honor terdeteksi; installer tidak akan mengubah file Slip Honor.');
  }

  ok(`Audit actual project PASS · package ${pkg.version ?? '-'}`);
}

const typesTs = "\nexport type InvoiceStatus = 'draft' | 'issued' | 'partial' | 'paid' | 'void';\nexport type PricingMode = 'hourly' | 'per_student';\nexport type RecipientKind = 'student' | 'organization';\n\nexport type InvoicePaymentMethod = {\n  id?: string | null;\n  method_type?: string | null;\n  label: string;\n  account_name?: string | null;\n  account_number?: string | null;\n  is_active?: boolean;\n  sort_order?: number;\n};\n\nexport type InvoiceSession = {\n  id?: string | null;\n  source_report_id?: string | null;\n  session_date: string;\n  starts_at: string;\n  ends_at: string;\n  duration_minutes: number;\n  sort_order?: number;\n};\n\nexport type InvoicePayment = {\n  id: string;\n  amount: number;\n  payment_date: string;\n  payment_method: string;\n  reference_number?: string | null;\n  notes?: string | null;\n  created_at?: string | null;\n};\n\nexport type InvoiceRow = {\n  id: string;\n  recipient_user_id?: string | null;\n  recipient_kind: RecipientKind;\n  class_id?: string | null;\n  invoice_code: string;\n  invoice_date: string;\n  due_date: string;\n  status: InvoiceStatus | string;\n  invoice_number?: string | null;\n  pricing_mode: PricingMode;\n  recipient_name: string;\n  recipient_address?: string | null;\n  recipient_phone?: string | null;\n  sender_name?: string | null;\n  sender_address?: string | null;\n  sender_phone?: string | null;\n  item_label: string;\n  class_name_snapshot?: string | null;\n  total_sessions: number;\n  total_minutes: number;\n  quantity: number;\n  unit_price: number;\n  subtotal: number;\n  additional_amount: number;\n  total_amount: number;\n  paid_amount: number;\n  payment_methods_snapshot?: InvoicePaymentMethod[];\n  notes?: string | null;\n  session_start?: string | null;\n  session_end?: string | null;\n  created_at?: string | null;\n  issued_at?: string | null;\n  paid_at?: string | null;\n  voided_at?: string | null;\n  void_reason?: string | null;\n};\n\nexport type InvoiceDetail = InvoiceRow & {\n  sessions: InvoiceSession[];\n  payments: InvoicePayment[];\n};\n\nexport type InvoiceSetup = {\n  organization?: {\n    sender_name?: string;\n    sender_address?: string;\n    sender_phone?: string;\n  } | null;\n  students: Array<{\n    user_id: string;\n    name: string;\n    billing_name?: string | null;\n    address?: string | null;\n    phone?: string | null;\n  }>;\n  classes: Array<{\n    id: string;\n    name: string;\n    code?: string | null;\n  }>;\n  payment_methods: InvoicePaymentMethod[];\n};\n\nexport type InvoiceOverview = {\n  rows: InvoiceRow[];\n  summary: {\n    total_invoices: number;\n    total_amount: number;\n    paid_amount: number;\n    outstanding_amount: number;\n    overdue_count: number;\n  };\n};\n";

const apiTs = "\nimport { supabase } from '../../lib/supabase';\nimport type {\n  InvoiceDetail,\n  InvoiceOverview,\n  InvoicePaymentMethod,\n  InvoiceRow,\n  InvoiceSetup,\n} from './types';\n\nfunction asRecord(value: unknown): Record<string, unknown> {\n  return value && typeof value === 'object' && !Array.isArray(value)\n    ? value as Record<string, unknown>\n    : {};\n}\n\nfunction asArray(value: unknown): unknown[] {\n  return Array.isArray(value) ? value : [];\n}\n\nfunction numberValue(value: unknown) {\n  const parsed = Number(value ?? 0);\n  return Number.isFinite(parsed) ? parsed : 0;\n}\n\nfunction textValue(value: unknown, fallback = '') {\n  return typeof value === 'string' ? value : fallback;\n}\n\nexport async function getManagementInvoiceSetup(): Promise<InvoiceSetup> {\n  const { data, error } = await supabase.rpc('get_management_invoice_setup');\n  if (error) throw error;\n\n  const raw = asRecord(data);\n  const organization = asRecord(raw.organization ?? raw.organization_settings ?? raw.sender);\n\n  const studentSource = asArray(raw.students ?? raw.student_options ?? raw.recipients);\n  const classSource = asArray(raw.classes ?? raw.class_options);\n  const paymentSource = asArray(raw.payment_methods ?? raw.paymentMethods);\n\n  return {\n    organization: {\n      sender_name: textValue(organization.sender_name ?? organization.name),\n      sender_address: textValue(organization.sender_address ?? organization.address),\n      sender_phone: textValue(organization.sender_phone ?? organization.phone),\n    },\n    students: studentSource.map((entry) => {\n      const row = asRecord(entry);\n      return {\n        user_id: textValue(row.user_id ?? row.id),\n        name: textValue(row.name ?? row.full_name ?? row.billing_name, 'Siswa KOJAC'),\n        billing_name: textValue(row.billing_name) || null,\n        address: textValue(row.address) || null,\n        phone: textValue(row.phone) || null,\n      };\n    }).filter((row) => row.user_id),\n    classes: classSource.map((entry) => {\n      const row = asRecord(entry);\n      return {\n        id: textValue(row.id ?? row.class_id),\n        name: textValue(row.name ?? row.class_name, 'Kelas KOJAC'),\n        code: textValue(row.code ?? row.class_code) || null,\n      };\n    }).filter((row) => row.id),\n    payment_methods: paymentSource.map((entry) => {\n      const row = asRecord(entry);\n      return {\n        id: textValue(row.id) || null,\n        method_type: textValue(row.method_type) || null,\n        label: textValue(row.label ?? row.name, 'Pembayaran'),\n        account_name: textValue(row.account_name) || null,\n        account_number: textValue(row.account_number) || null,\n        is_active: row.is_active !== false,\n        sort_order: numberValue(row.sort_order),\n      } satisfies InvoicePaymentMethod;\n    }),\n  };\n}\n\nfunction normalizeInvoice(entry: unknown): InvoiceRow {\n  const row = asRecord(entry);\n  return {\n    id: textValue(row.id ?? row.invoice_id),\n    recipient_user_id: textValue(row.recipient_user_id) || null,\n    recipient_kind: (textValue(row.recipient_kind, 'student') as InvoiceRow['recipient_kind']),\n    class_id: textValue(row.class_id) || null,\n    invoice_code: textValue(row.invoice_code, 'JPNPRIVAT'),\n    invoice_date: textValue(row.invoice_date),\n    due_date: textValue(row.due_date),\n    status: textValue(row.status, 'draft'),\n    invoice_number: textValue(row.invoice_number) || null,\n    pricing_mode: (textValue(row.pricing_mode, 'hourly') as InvoiceRow['pricing_mode']),\n    recipient_name: textValue(row.recipient_name, 'Penerima'),\n    recipient_address: textValue(row.recipient_address) || null,\n    recipient_phone: textValue(row.recipient_phone) || null,\n    sender_name: textValue(row.sender_name) || null,\n    sender_address: textValue(row.sender_address) || null,\n    sender_phone: textValue(row.sender_phone) || null,\n    item_label: textValue(row.item_label, 'Kelas Bahasa Jepang'),\n    class_name_snapshot: textValue(row.class_name_snapshot) || null,\n    total_sessions: numberValue(row.total_sessions),\n    total_minutes: numberValue(row.total_minutes),\n    quantity: numberValue(row.quantity),\n    unit_price: numberValue(row.unit_price),\n    subtotal: numberValue(row.subtotal),\n    additional_amount: numberValue(row.additional_amount),\n    total_amount: numberValue(row.total_amount),\n    paid_amount: numberValue(row.paid_amount),\n    payment_methods_snapshot: asArray(row.payment_methods_snapshot) as InvoicePaymentMethod[],\n    notes: textValue(row.notes) || null,\n    session_start: textValue(row.session_start) || null,\n    session_end: textValue(row.session_end) || null,\n    created_at: textValue(row.created_at) || null,\n    issued_at: textValue(row.issued_at) || null,\n    paid_at: textValue(row.paid_at) || null,\n    voided_at: textValue(row.voided_at) || null,\n    void_reason: textValue(row.void_reason) || null,\n  };\n}\n\nexport async function getManagementInvoiceOverview(month: string): Promise<InvoiceOverview> {\n  const { data, error } = await supabase.rpc('get_management_invoice_overview', { p_month: month });\n  if (error) throw error;\n\n  const raw = asRecord(data);\n  const rowsSource = asArray(raw.rows ?? raw.invoices ?? data);\n  const rows = rowsSource.map(normalizeInvoice).filter((row) => row.id);\n  const summary = asRecord(raw.summary);\n\n  const computedTotal = rows.reduce((sum, row) => sum + row.total_amount, 0);\n  const computedPaid = rows.reduce((sum, row) => sum + row.paid_amount, 0);\n\n  return {\n    rows,\n    summary: {\n      total_invoices: numberValue(summary.total_invoices ?? rows.length),\n      total_amount: numberValue(summary.total_amount ?? computedTotal),\n      paid_amount: numberValue(summary.paid_amount ?? computedPaid),\n      outstanding_amount: numberValue(summary.outstanding_amount ?? (computedTotal - computedPaid)),\n      overdue_count: numberValue(summary.overdue_count),\n    },\n  };\n}\n\nexport async function saveManagementInvoice(payload: Record<string, unknown>) {\n  const { data, error } = await supabase.rpc('save_management_invoice', { p_payload: payload });\n  if (error) throw error;\n  return String(data);\n}\n\nexport async function issueManagementInvoice(invoiceId: string) {\n  const { data, error } = await supabase.rpc('issue_management_invoice', { p_invoice_id: invoiceId });\n  if (error) throw error;\n  return String(data ?? '');\n}\n\nexport async function recordInvoicePayment(args: {\n  invoiceId: string;\n  amount: number;\n  paymentDate: string;\n  paymentMethod: string;\n  referenceNumber?: string;\n  notes?: string;\n}) {\n  const { data, error } = await supabase.rpc('record_management_invoice_payment', {\n    p_invoice_id: args.invoiceId,\n    p_amount: Math.trunc(args.amount),\n    p_payment_date: args.paymentDate,\n    p_payment_method: args.paymentMethod,\n    p_reference_number: args.referenceNumber?.trim() || null,\n    p_notes: args.notes?.trim() || null,\n  });\n  if (error) throw error;\n  return data;\n}\n\nexport async function voidManagementInvoice(invoiceId: string, reason: string) {\n  const { error } = await supabase.rpc('void_management_invoice', {\n    p_invoice_id: invoiceId,\n    p_reason: reason.trim(),\n  });\n  if (error) throw error;\n}\n\nexport async function getInvoiceDetail(invoiceId: string): Promise<InvoiceDetail> {\n  const { data, error } = await supabase.rpc('get_invoice_detail', { p_invoice_id: invoiceId });\n  if (error) throw error;\n\n  const raw = asRecord(data);\n  const invoiceRaw = asRecord(raw.invoice ?? data);\n  const invoice = normalizeInvoice(invoiceRaw);\n\n  return {\n    ...invoice,\n    sessions: asArray(raw.sessions ?? invoiceRaw.sessions).map((entry, index) => {\n      const row = asRecord(entry);\n      return {\n        id: textValue(row.id) || null,\n        source_report_id: textValue(row.source_report_id) || null,\n        session_date: textValue(row.session_date),\n        starts_at: textValue(row.starts_at),\n        ends_at: textValue(row.ends_at),\n        duration_minutes: numberValue(row.duration_minutes),\n        sort_order: numberValue(row.sort_order ?? index),\n      };\n    }),\n    payments: asArray(raw.payments ?? invoiceRaw.payments).map((entry) => {\n      const row = asRecord(entry);\n      return {\n        id: textValue(row.id),\n        amount: numberValue(row.amount),\n        payment_date: textValue(row.payment_date),\n        payment_method: textValue(row.payment_method),\n        reference_number: textValue(row.reference_number) || null,\n        notes: textValue(row.notes) || null,\n        created_at: textValue(row.created_at) || null,\n      };\n    }).filter((row) => row.id),\n  };\n}\n\nexport async function getMyInvoices(): Promise<InvoiceRow[]> {\n  const { data, error } = await supabase.rpc('get_my_invoices');\n  if (error) throw error;\n  const raw = asRecord(data);\n  return asArray(raw.rows ?? raw.invoices ?? data).map(normalizeInvoice).filter((row) => row.id);\n}\n";

const pdfTs = "\nimport type { InvoiceDetail } from './types';\n\nfunction escapeHtml(value: unknown) {\n  return String(value ?? '')\n    .replaceAll('&', '&amp;')\n    .replaceAll('<', '&lt;')\n    .replaceAll('>', '&gt;')\n    .replaceAll('\"', '&quot;')\n    .replaceAll(\"'\", '&#039;');\n}\n\nfunction rupiah(value: number) {\n  return new Intl.NumberFormat('id-ID', {\n    style: 'currency',\n    currency: 'IDR',\n    maximumFractionDigits: 0,\n  }).format(value || 0);\n}\n\nfunction dateId(value: string | null | undefined) {\n  if (!value) return '—';\n  const date = new Date(value.includes('T') ? value : value + 'T00:00:00+07:00');\n  if (!Number.isFinite(date.getTime())) return value;\n  return new Intl.DateTimeFormat('id-ID', {\n    timeZone: 'Asia/Jakarta',\n    day: '2-digit',\n    month: 'long',\n    year: 'numeric',\n  }).format(date);\n}\n\nfunction durationHours(minutes: number) {\n  const hours = Math.max(0, Number(minutes || 0)) / 60;\n  return Number.isInteger(hours) ? String(hours) : hours.toFixed(2).replace('.', ',');\n}\n\nconst units = ['', 'satu', 'dua', 'tiga', 'empat', 'lima', 'enam', 'tujuh', 'delapan', 'sembilan', 'sepuluh', 'sebelas'];\n\nfunction words(n: number): string {\n  n = Math.floor(Math.abs(n));\n  if (n < 12) return units[n];\n  if (n < 20) return words(n - 10) + ' belas';\n  if (n < 100) return words(Math.floor(n / 10)) + ' puluh' + (n % 10 ? ' ' + words(n % 10) : '');\n  if (n < 200) return 'seratus' + (n > 100 ? ' ' + words(n - 100) : '');\n  if (n < 1000) return words(Math.floor(n / 100)) + ' ratus' + (n % 100 ? ' ' + words(n % 100) : '');\n  if (n < 2000) return 'seribu' + (n > 1000 ? ' ' + words(n - 1000) : '');\n  if (n < 1_000_000) return words(Math.floor(n / 1000)) + ' ribu' + (n % 1000 ? ' ' + words(n % 1000) : '');\n  if (n < 1_000_000_000) return words(Math.floor(n / 1_000_000)) + ' juta' + (n % 1_000_000 ? ' ' + words(n % 1_000_000) : '');\n  return String(n);\n}\n\nfunction paymentMethodsHtml(detail: InvoiceDetail) {\n  const methods = detail.payment_methods_snapshot ?? [];\n  if (!methods.length) return '<div class=\"muted\">Metode pembayaran mengikuti informasi resmi KOJAC.</div>';\n  return methods.map((method) => [\n    '<div class=\"payment-row\">',\n    '<strong>', escapeHtml(method.label), '</strong>',\n    method.account_number ? '<span>' + escapeHtml(method.account_number) + '</span>' : '',\n    method.account_name ? '<span>a.n. ' + escapeHtml(method.account_name) + '</span>' : '',\n    '</div>',\n  ].join('')).join('');\n}\n\nexport function printInvoicePdf(detail: InvoiceDetail) {\n  const win = window.open('', '_blank', 'noopener,noreferrer');\n  if (!win) throw new Error('popup_blocked');\n\n  const isHourly = detail.pricing_mode === 'hourly';\n  const totalHours = detail.total_minutes / 60;\n  const outstanding = Math.max(0, detail.total_amount - detail.paid_amount);\n  const sessions = [...detail.sessions].sort((a, b) =>\n    (a.session_date + a.starts_at).localeCompare(b.session_date + b.starts_at)\n  );\n\n  const sessionRows = sessions.length\n    ? sessions.map((session, index) => [\n        '<tr><td>', index + 1, '</td><td>', escapeHtml(dateId(session.session_date)), '</td>',\n        '<td>', escapeHtml(session.starts_at?.slice(0,5)), ' – ', escapeHtml(session.ends_at?.slice(0,5)), '</td>',\n        '<td>', escapeHtml(durationHours(session.duration_minutes)), '</td></tr>'\n      ].join('')).join('')\n    : '<tr><td colspan=\"4\" class=\"empty\">Belum ada rekap sesi.</td></tr>';\n\n  const html = `<!doctype html>\n<html lang=\"id\">\n<head>\n<meta charset=\"utf-8\"/>\n<title>${escapeHtml(detail.invoice_number || 'Invoice KOJAC')}</title>\n<style>\n@page{size:A4;margin:0}\n*{box-sizing:border-box}\nbody{margin:0;background:#ece8e9;font-family:Arial,Helvetica,sans-serif;color:#2d2426}\n.page{width:210mm;min-height:297mm;margin:0 auto;background:#fff;padding:17mm 17mm 15mm;position:relative}\n.page+.page{page-break-before:always}\n.top{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;border-bottom:3px solid #741e31;padding-bottom:12px}\n.logo{height:44px;max-width:170px;object-fit:contain}\n.invoice-title{text-align:right}\n.invoice-title h1{margin:0;color:#741e31;font-size:29px;letter-spacing:2px}\n.invoice-title p{margin:5px 0 0;font-size:10px;color:#776a6d}\n.meta{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin:14px 0}\n.meta div{border:1px solid #eadfe2;border-radius:8px;padding:9px}\n.meta span,.party span,.summary span{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.08em;color:#8b777c;margin-bottom:3px}\n.meta strong,.party strong,.summary strong{font-size:10px}\n.parties{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:12px 0 15px}\n.party{background:#faf6f7;border-left:4px solid #741e31;padding:11px 12px;min-height:88px}\n.party p{margin:4px 0;font-size:9px;line-height:1.45}\ntable{width:100%;border-collapse:collapse}\nth{background:#741e31;color:#fff;padding:8px;font-size:8px;text-align:left;text-transform:uppercase}\ntd{padding:8px;border-bottom:1px solid #eadfe2;font-size:9px;vertical-align:top}\n.money{text-align:right;white-space:nowrap}\n.totals{width:52%;margin:12px 0 12px auto}\n.total-row{display:flex;justify-content:space-between;padding:6px 3px;border-bottom:1px solid #eadfe2;font-size:9px}\n.total-row.grand{border-bottom:none;background:#741e31;color:#fff;padding:9px;font-weight:700}\n.terbilang{margin:12px 0;padding:10px;background:#faf6f7;border-radius:8px;font-size:9px}\n.section-title{font-size:9px;color:#741e31;font-weight:800;letter-spacing:.06em;margin:15px 0 7px;text-transform:uppercase}\n.payment-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.payment-row{border:1px solid #eadfe2;border-radius:8px;padding:8px;display:grid;gap:3px;font-size:8px}\n.payment-row strong{font-size:9px}\n.note{font-size:8.5px;line-height:1.55;color:#57484b}\n.thanks{text-align:center;margin-top:20px;font-weight:800;color:#741e31;font-size:10px}\n.footer{position:absolute;left:17mm;right:17mm;bottom:10mm;border-top:1px solid #eadfe2;padding-top:6px;display:flex;justify-content:space-between;font-size:7.5px;color:#8b777c}\n.recap-head{text-align:center;margin-bottom:16px}\n.recap-head img{height:38px;margin-bottom:10px}\n.recap-head h1{font-size:19px;letter-spacing:.08em;color:#741e31;margin:0}\n.recap-head p{font-size:9px;color:#776a6d}\n.recap-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px}\n.summary{border:1px solid #eadfe2;border-radius:8px;padding:9px}\n.empty{text-align:center;color:#99878b;padding:28px}\n.status{display:inline-block;padding:4px 8px;border-radius:999px;background:#f2e7ea;color:#741e31;font-weight:700}\n@media print{body{background:#fff}.page{margin:0;box-shadow:none}}\n</style>\n</head>\n<body>\n<section class=\"page\">\n  <div class=\"top\">\n    <img class=\"logo\" src=\"${location.origin}/brand/kojac-wordmark.png\" alt=\"KOJAC\"/>\n    <div class=\"invoice-title\">\n      <h1>INVOICE</h1>\n      <p>${escapeHtml(detail.invoice_number || 'DRAFT · nomor diterbitkan saat Issue')}</p>\n    </div>\n  </div>\n\n  <div class=\"meta\">\n    <div><span>Tanggal Invoice</span><strong>${escapeHtml(dateId(detail.invoice_date))}</strong></div>\n    <div><span>Jatuh Tempo</span><strong>${escapeHtml(dateId(detail.due_date))}</strong></div>\n    <div><span>Status</span><strong class=\"status\">${escapeHtml(detail.status.toUpperCase())}</strong></div>\n  </div>\n\n  <div class=\"parties\">\n    <div class=\"party\">\n      <span>Kepada</span>\n      <strong>${escapeHtml(detail.recipient_name)}</strong>\n      <p>${escapeHtml(detail.recipient_address || '—')}</p>\n      <p>${escapeHtml(detail.recipient_phone || '—')}</p>\n    </div>\n    <div class=\"party\">\n      <span>Dari</span>\n      <strong>${escapeHtml(detail.sender_name || 'KOJAC — Kuuhaku Online Japanese Class')}</strong>\n      <p>${escapeHtml(detail.sender_address || '—')}</p>\n      <p>${escapeHtml(detail.sender_phone || '—')}</p>\n    </div>\n  </div>\n\n  <div class=\"section-title\">Deskripsi</div>\n  <table>\n    <thead>\n      <tr>\n        <th>${isHourly ? 'Nama Kelas' : 'Jenis Kelas'}</th>\n        <th>${isHourly ? 'Total Sesi' : 'Nama Kelas'}</th>\n        <th>${isHourly ? 'Total Jam' : 'Jumlah Siswa'}</th>\n        <th>${isHourly ? 'Biaya per Jam' : 'Biaya per Siswa'}</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td>${escapeHtml(detail.item_label)}</td>\n        <td>${escapeHtml(isHourly ? detail.total_sessions : (detail.class_name_snapshot || detail.item_label))}</td>\n        <td>${escapeHtml(isHourly ? durationHours(detail.total_minutes) : detail.quantity)}</td>\n        <td class=\"money\">${escapeHtml(rupiah(detail.unit_price))}</td>\n      </tr>\n    </tbody>\n  </table>\n\n  <div class=\"totals\">\n    <div class=\"total-row\"><span>Subtotal</span><strong>${escapeHtml(rupiah(detail.subtotal))}</strong></div>\n    <div class=\"total-row\"><span>Tambahan / Lain-lain</span><strong>${escapeHtml(rupiah(detail.additional_amount))}</strong></div>\n    <div class=\"total-row\"><span>Sudah Dibayar</span><strong>${escapeHtml(rupiah(detail.paid_amount))}</strong></div>\n    <div class=\"total-row\"><span>Sisa Tagihan</span><strong>${escapeHtml(rupiah(outstanding))}</strong></div>\n    <div class=\"total-row grand\"><span>Total Keseluruhan</span><strong>${escapeHtml(rupiah(detail.total_amount))}</strong></div>\n  </div>\n\n  <div class=\"terbilang\"><strong>Terbilang:</strong> ${escapeHtml(words(detail.total_amount).replace(/^./, c => c.toUpperCase()))} rupiah.</div>\n\n  <div class=\"section-title\">Metode Pembayaran</div>\n  <div class=\"payment-grid\">${paymentMethodsHtml(detail)}</div>\n\n  <div class=\"section-title\">Catatan</div>\n  <div class=\"note\">${escapeHtml(detail.notes || 'Mohon melakukan pembayaran sesuai nominal dan jatuh tempo yang tercantum pada invoice.')}</div>\n\n  <div class=\"thanks\">Terima kasih telah belajar bersama KOJAC.</div>\n  <div class=\"footer\">\n    <span>KOJAC · Kuuhaku Online Japanese Class</span>\n    <span>${escapeHtml(detail.invoice_number || 'DRAFT')}</span>\n  </div>\n</section>\n\n<section class=\"page\">\n  <div class=\"recap-head\">\n    <img src=\"${location.origin}/brand/kojac-wordmark.png\" alt=\"KOJAC\"/>\n    <h1>REKAPAN SESI KELAS</h1>\n    <p>${escapeHtml(detail.class_name_snapshot || detail.item_label)} · ${escapeHtml(detail.invoice_number || 'DRAFT')}</p>\n  </div>\n\n  <div class=\"recap-summary\">\n    <div class=\"summary\"><span>Total Sesi</span><strong>${escapeHtml(detail.total_sessions)}</strong></div>\n    <div class=\"summary\"><span>Total Jam</span><strong>${escapeHtml(durationHours(detail.total_minutes))} jam</strong></div>\n    <div class=\"summary\"><span>Periode</span><strong>${escapeHtml(detail.session_start ? dateId(detail.session_start) : '—')} – ${escapeHtml(detail.session_end ? dateId(detail.session_end) : '—')}</strong></div>\n  </div>\n\n  <table>\n    <thead><tr><th>No.</th><th>Tanggal</th><th>Waktu (WIB)</th><th>Jam</th></tr></thead>\n    <tbody>${sessionRows}</tbody>\n    <tfoot><tr><td colspan=\"3\"><strong>Total (jam)</strong></td><td><strong>${escapeHtml(durationHours(detail.total_minutes))}</strong></td></tr></tfoot>\n  </table>\n\n  <div class=\"footer\">\n    <span>Rekapan sesi kelas · KOJAC</span>\n    <span>${escapeHtml(detail.invoice_number || 'DRAFT')}</span>\n  </div>\n</section>\n\n<script>\nwindow.addEventListener('load', () => setTimeout(() => window.print(), 250));\n</script>\n</body></html>`;\n\n  win.document.open();\n  win.document.write(html);\n  win.document.close();\n}\n";

const detailPageTsx = "\nimport { ArrowLeft, FileDown, RefreshCw } from 'lucide-react';\nimport { useCallback, useEffect, useState } from 'react';\nimport { Link, useParams } from 'react-router-dom';\nimport { getInvoiceDetail } from '../features/invoice/api';\nimport { printInvoicePdf } from '../features/invoice/invoicePdf';\nimport type { InvoiceDetail } from '../features/invoice/types';\nimport '../features/invoice/invoice.css';\n\nfunction rupiah(value: number) {\n  return new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value || 0);\n}\nfunction dateId(value?: string | null) {\n  if (!value) return '—';\n  const date = new Date(value.includes('T') ? value : value + 'T00:00:00+07:00');\n  return Number.isFinite(date.getTime())\n    ? new Intl.DateTimeFormat('id-ID', { timeZone: 'Asia/Jakarta', day: '2-digit', month: 'short', year: 'numeric' }).format(date)\n    : value;\n}\nfunction statusLabel(status: string) {\n  return ({ draft:'Draft', issued:'Terbit', partial:'Sebagian', paid:'Lunas', void:'Dibatalkan' } as Record<string,string>)[status] || status;\n}\n\nexport function InvoiceDetailPage() {\n  const { invoiceId } = useParams();\n  const [detail, setDetail] = useState<InvoiceDetail | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n\n  const load = useCallback(async () => {\n    if (!invoiceId) return;\n    setLoading(true);\n    setError('');\n    try {\n      setDetail(await getInvoiceDetail(invoiceId));\n    } catch (loadError) {\n      console.error('KOJAC invoice detail load failed', loadError);\n      setError('Invoice belum dapat dimuat.');\n    } finally {\n      setLoading(false);\n    }\n  }, [invoiceId]);\n\n  useEffect(() => { void load(); }, [load]);\n\n  if (loading) return <div className=\"full-center\">Memuat invoice…</div>;\n  if (!detail) return <div className=\"page invoice-page\"><div className=\"invoice-state\">{error || 'Invoice tidak ditemukan.'}<button onClick={() => void load()}><RefreshCw size={15}/> Coba Lagi</button></div></div>;\n\n  const outstanding = Math.max(0, detail.total_amount - detail.paid_amount);\n\n  return <div className=\"page invoice-page\">\n    <header className=\"invoice-header\">\n      <div>\n        <p className=\"eyebrow\">KOJAC · INVOICE</p>\n        <h1>{detail.invoice_number || 'Draft Invoice'}</h1>\n        <p>{detail.recipient_name} · {detail.class_name_snapshot || detail.item_label}</p>\n      </div>\n      <div className=\"invoice-header-actions\">\n        <Link className=\"invoice-btn secondary\" to={history.length > 1 ? -1 as never : '/'}><ArrowLeft size={15}/> Kembali</Link>\n        <button className=\"invoice-btn primary\" onClick={() => printInvoicePdf(detail)}><FileDown size={15}/> PDF / Print</button>\n      </div>\n    </header>\n\n    <section className=\"invoice-detail-grid\">\n      <article className=\"invoice-card\"><span>Status</span><strong className={\"invoice-status is-\" + detail.status}>{statusLabel(detail.status)}</strong></article>\n      <article className=\"invoice-card\"><span>Tanggal</span><strong>{dateId(detail.invoice_date)}</strong></article>\n      <article className=\"invoice-card\"><span>Jatuh Tempo</span><strong>{dateId(detail.due_date)}</strong></article>\n      <article className=\"invoice-card\"><span>Sisa Tagihan</span><strong>{rupiah(outstanding)}</strong></article>\n    </section>\n\n    <section className=\"invoice-panel\">\n      <div className=\"invoice-section-title\"><div><p className=\"eyebrow\">TAGIHAN</p><h2>Rincian Invoice</h2></div></div>\n      <div className=\"invoice-info-grid\">\n        <div><span>Penerima</span><strong>{detail.recipient_name}</strong><small>{detail.recipient_address || '—'}<br/>{detail.recipient_phone || '—'}</small></div>\n        <div><span>Kelas</span><strong>{detail.class_name_snapshot || detail.item_label}</strong><small>{detail.pricing_mode === 'hourly' ? 'Per jam' : 'Per siswa'}</small></div>\n        <div><span>Tarif</span><strong>{rupiah(detail.unit_price)}</strong><small>{detail.pricing_mode === 'hourly' ? `${(detail.total_minutes/60).toFixed(2)} jam` : `${detail.quantity} siswa`}</small></div>\n        <div><span>Total</span><strong>{rupiah(detail.total_amount)}</strong><small>Terbayar {rupiah(detail.paid_amount)}</small></div>\n      </div>\n      {detail.notes && <div className=\"invoice-note\"><strong>Catatan</strong><p>{detail.notes}</p></div>}\n    </section>\n\n    <section className=\"invoice-panel\">\n      <div className=\"invoice-section-title\"><div><p className=\"eyebrow\">HALAMAN 2 PDF</p><h2>Rekapan Sesi Kelas</h2></div><span>{detail.sessions.length} sesi</span></div>\n      <div className=\"invoice-table-wrap\">\n        <table className=\"invoice-table\">\n          <thead><tr><th>Tanggal</th><th>Waktu (WIB)</th><th>Durasi</th></tr></thead>\n          <tbody>\n            {detail.sessions.length ? detail.sessions.map((session, i) => <tr key={session.id || i}>\n              <td>{dateId(session.session_date)}</td>\n              <td>{session.starts_at?.slice(0,5)} – {session.ends_at?.slice(0,5)}</td>\n              <td>{session.duration_minutes} menit</td>\n            </tr>) : <tr><td colSpan={3}>Belum ada rekap sesi.</td></tr>}\n          </tbody>\n        </table>\n      </div>\n    </section>\n\n    <section className=\"invoice-panel\">\n      <div className=\"invoice-section-title\"><div><p className=\"eyebrow\">PEMBAYARAN</p><h2>Histori Pembayaran</h2></div></div>\n      <div className=\"invoice-payment-list\">\n        {detail.payments.length ? detail.payments.map(payment => <article key={payment.id}>\n          <div><strong>{rupiah(payment.amount)}</strong><span>{dateId(payment.payment_date)}</span></div>\n          <div><span>{payment.payment_method}</span><small>{payment.reference_number || 'Tanpa referensi'}</small></div>\n        </article>) : <div className=\"invoice-empty\">Belum ada pembayaran tercatat.</div>}\n      </div>\n    </section>\n  </div>;\n}\n";

const myInvoicesTsx = "\nimport { FileText, RefreshCw } from 'lucide-react';\nimport { useCallback, useEffect, useState } from 'react';\nimport { Link, Navigate } from 'react-router-dom';\nimport { getMyInvoices } from '../features/invoice/api';\nimport type { InvoiceRow } from '../features/invoice/types';\nimport { useAuth } from '../state/AuthContext';\nimport '../features/invoice/invoice.css';\n\nfunction rupiah(value: number) {\n  return new Intl.NumberFormat('id-ID', { style:'currency', currency:'IDR', maximumFractionDigits:0 }).format(value || 0);\n}\nfunction dateId(value?: string | null) {\n  if (!value) return '—';\n  const date = new Date(value + (value.includes('T') ? '' : 'T00:00:00+07:00'));\n  return Number.isFinite(date.getTime()) ? new Intl.DateTimeFormat('id-ID', { timeZone:'Asia/Jakarta', day:'2-digit', month:'short', year:'numeric' }).format(date) : value;\n}\nfunction statusLabel(status: string) {\n  return ({ draft:'Draft', issued:'Terbit', partial:'Sebagian', paid:'Lunas', void:'Dibatalkan' } as Record<string,string>)[status] || status;\n}\n\nexport function MyInvoicesPage() {\n  const { role, loading: authLoading } = useAuth();\n  const [rows, setRows] = useState<InvoiceRow[]>([]);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState('');\n\n  const load = useCallback(async () => {\n    setLoading(true); setError('');\n    try { setRows(await getMyInvoices()); }\n    catch (err) { console.error('KOJAC my invoices load failed', err); setError('Tagihan belum dapat dimuat.'); }\n    finally { setLoading(false); }\n  }, []);\n\n  useEffect(() => { if (!authLoading && role === 'siswa') void load(); }, [authLoading, role, load]);\n\n  if (authLoading) return <div className=\"full-center\">Memuat KOJAC LMS…</div>;\n  if (role !== 'siswa') return <Navigate to=\"/\" replace/>;\n\n  const outstanding = rows.filter(r => !['paid','void'].includes(r.status)).reduce((sum,r)=>sum+Math.max(0,r.total_amount-r.paid_amount),0);\n\n  return <div className=\"page invoice-page\">\n    <header className=\"invoice-header\">\n      <div><p className=\"eyebrow\">SISWA KOJAC</p><h1>Tagihan Saya</h1><p>Lihat invoice, jatuh tempo, pembayaran, dan rekap sesi.</p></div>\n    </header>\n\n    <section className=\"invoice-detail-grid\">\n      <article className=\"invoice-card\"><span>Total Invoice</span><strong>{rows.length}</strong></article>\n      <article className=\"invoice-card\"><span>Belum Lunas</span><strong>{rows.filter(r=>!['paid','void'].includes(r.status)).length}</strong></article>\n      <article className=\"invoice-card wide\"><span>Sisa Tagihan</span><strong>{rupiah(outstanding)}</strong></article>\n    </section>\n\n    {loading ? <div className=\"invoice-state\">Memuat tagihan…</div> :\n     error ? <div className=\"invoice-state\">{error}<button onClick={() => void load()}><RefreshCw size={15}/> Coba Lagi</button></div> :\n     rows.length === 0 ? <div className=\"invoice-state\"><FileText size={30}/><strong>Belum ada tagihan.</strong><span>Invoice yang sudah diterbitkan akan tampil di sini.</span></div> :\n     <section className=\"invoice-list\">\n       {rows.map(row => <Link key={row.id} to={\"/invoice/\" + row.id} className=\"invoice-list-row\">\n         <div><strong>{row.invoice_number || 'Draft Invoice'}</strong><span>{row.class_name_snapshot || row.item_label}</span></div>\n         <div><span>Jatuh tempo</span><strong>{dateId(row.due_date)}</strong></div>\n         <div><span>Total</span><strong>{rupiah(row.total_amount)}</strong></div>\n         <div><span className={\"invoice-status is-\" + row.status}>{statusLabel(row.status)}</span></div>\n       </Link>)}\n     </section>}\n  </div>;\n}\n";

const managementTsx = "\nimport { Ban, CheckCircle2, CircleDollarSign, FilePlus2, FileText, RefreshCw, Save, Search } from 'lucide-react';\nimport { useCallback, useEffect, useMemo, useState } from 'react';\nimport { Navigate, useNavigate } from 'react-router-dom';\nimport {\n  getManagementInvoiceOverview,\n  getManagementInvoiceSetup,\n  issueManagementInvoice,\n  recordInvoicePayment,\n  saveManagementInvoice,\n  voidManagementInvoice,\n} from '../features/invoice/api';\nimport type { InvoiceOverview, InvoiceRow, InvoiceSession, InvoiceSetup, PricingMode, RecipientKind } from '../features/invoice/types';\nimport { useAuth } from '../state/AuthContext';\nimport type { AppRole } from '../types';\nimport '../features/invoice/invoice.css';\n\nconst MANAGEMENT_ROLES = new Set<AppRole>(['administrator','manager','co_founder','founder']);\n\nfunction today() { return new Date().toISOString().slice(0,10); }\nfunction monthStart() { return today().slice(0,7) + '-01'; }\nfunction rupiah(value: number) { return new Intl.NumberFormat('id-ID', { style:'currency', currency:'IDR', maximumFractionDigits:0 }).format(value || 0); }\nfunction dateId(value?: string | null) {\n  if (!value) return '—';\n  const d = new Date(value + (value.includes('T') ? '' : 'T00:00:00+07:00'));\n  return Number.isFinite(d.getTime()) ? new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',day:'2-digit',month:'short',year:'numeric'}).format(d) : value;\n}\nfunction statusLabel(status: string) {\n  return ({ draft:'Draft', issued:'Terbit', partial:'Sebagian', paid:'Lunas', void:'Dibatalkan' } as Record<string,string>)[status] || status;\n}\nfunction emptySession(): InvoiceSession {\n  return { session_date: today(), starts_at:'19:30', ends_at:'21:00', duration_minutes:90 };\n}\nfunction calcDuration(start: string, end: string) {\n  const [sh,sm] = start.split(':').map(Number), [eh,em] = end.split(':').map(Number);\n  if ([sh,sm,eh,em].some(v=>!Number.isFinite(v))) return 0;\n  return Math.max(0,(eh*60+em)-(sh*60+sm));\n}\n\ntype Draft = {\n  id?: string;\n  recipient_kind: RecipientKind;\n  recipient_user_id: string;\n  recipient_name: string;\n  recipient_address: string;\n  recipient_phone: string;\n  class_id: string;\n  class_name_snapshot: string;\n  invoice_code: string;\n  invoice_date: string;\n  due_date: string;\n  pricing_mode: PricingMode;\n  item_label: string;\n  quantity: number;\n  unit_price: number;\n  additional_amount: number;\n  notes: string;\n  sessions: InvoiceSession[];\n};\n\nfunction freshDraft(): Draft {\n  return {\n    recipient_kind:'student', recipient_user_id:'', recipient_name:'', recipient_address:'', recipient_phone:'',\n    class_id:'', class_name_snapshot:'', invoice_code:'JPNPRIVAT', invoice_date:today(), due_date:today(),\n    pricing_mode:'hourly', item_label:'PRIVAT 1 ON 1', quantity:1, unit_price:0, additional_amount:0, notes:'',\n    sessions:[emptySession()],\n  };\n}\n\nexport function ManagementInvoicesPage() {\n  const { role, loading: authLoading } = useAuth();\n  const canManage = Boolean(role && MANAGEMENT_ROLES.has(role));\n  const navigate = useNavigate();\n\n  const [setup, setSetup] = useState<InvoiceSetup | null>(null);\n  const [overview, setOverview] = useState<InvoiceOverview | null>(null);\n  const [month, setMonth] = useState(monthStart());\n  const [search, setSearch] = useState('');\n  const [loading, setLoading] = useState(true);\n  const [message, setMessage] = useState('');\n  const [formOpen, setFormOpen] = useState(false);\n  const [draft, setDraft] = useState<Draft>(freshDraft());\n  const [busy, setBusy] = useState(false);\n\n  const load = useCallback(async () => {\n    if (!canManage) return;\n    setLoading(true); setMessage('');\n    try {\n      const [nextSetup,nextOverview] = await Promise.all([\n        getManagementInvoiceSetup(),\n        getManagementInvoiceOverview(month),\n      ]);\n      setSetup(nextSetup); setOverview(nextOverview);\n    } catch (error) {\n      console.error('KOJAC invoice management load failed', error);\n      setMessage('Data invoice belum dapat dimuat.');\n    } finally { setLoading(false); }\n  }, [canManage, month]);\n\n  useEffect(()=>{ if(!authLoading && canManage) void load(); },[authLoading,canManage,load]);\n\n  const rows = useMemo(() => {\n    const query = search.trim().toLowerCase();\n    const source = overview?.rows ?? [];\n    if (!query) return source;\n    return source.filter(row => [row.invoice_number,row.recipient_name,row.class_name_snapshot,row.item_label].some(v=>String(v??'').toLowerCase().includes(query)));\n  }, [overview,search]);\n\n  if (authLoading) return <div className=\"full-center\">Memuat KOJAC LMS…</div>;\n  if (!canManage) return <Navigate to=\"/\" replace/>;\n\n  const totalMinutes = draft.sessions.reduce((sum,s)=>sum+(Number(s.duration_minutes)||0),0);\n  const totalSessions = draft.sessions.length;\n  const quantity = draft.pricing_mode === 'hourly' ? totalMinutes / 60 : Number(draft.quantity || 0);\n  const subtotal = Math.round(quantity * Number(draft.unit_price || 0));\n  const total = subtotal + Number(draft.additional_amount || 0);\n\n  function openNew() { setDraft(freshDraft()); setFormOpen(true); setMessage(''); }\n\n  function selectStudent(userId: string) {\n    const student = setup?.students.find(s=>s.user_id===userId);\n    setDraft(current => ({\n      ...current,\n      recipient_user_id:userId,\n      recipient_name: student?.billing_name || student?.name || '',\n      recipient_address: student?.address || '',\n      recipient_phone: student?.phone || '',\n    }));\n  }\n\n  function selectClass(classId: string) {\n    const cls = setup?.classes.find(c=>c.id===classId);\n    setDraft(current=>({...current,class_id:classId,class_name_snapshot:cls?.name||'',item_label:cls?.name||current.item_label}));\n  }\n\n  function updateSession(index: number, patch: Partial<InvoiceSession>) {\n    setDraft(current=>({...current,sessions:current.sessions.map((s,i)=>{\n      if(i!==index) return s;\n      const next={...s,...patch};\n      if(patch.starts_at !== undefined || patch.ends_at !== undefined) next.duration_minutes=calcDuration(next.starts_at,next.ends_at);\n      return next;\n    })}));\n  }\n\n  async function saveDraft() {\n    if (!draft.recipient_name.trim()) return setMessage('Nama penerima wajib diisi.');\n    if (!draft.invoice_code.trim()) return setMessage('Kode invoice wajib diisi.');\n    if (draft.unit_price <= 0) return setMessage('Tarif harus lebih dari 0.');\n    setBusy(true); setMessage('');\n    try {\n      const id = await saveManagementInvoice({\n        id: draft.id || null,\n        recipient_kind:draft.recipient_kind,\n        recipient_user_id:draft.recipient_kind==='student' ? draft.recipient_user_id || null : null,\n        recipient_name:draft.recipient_name.trim(),\n        recipient_address:draft.recipient_address.trim() || null,\n        recipient_phone:draft.recipient_phone.trim() || null,\n        class_id:draft.class_id || null,\n        class_name_snapshot:draft.class_name_snapshot.trim() || null,\n        invoice_code:draft.invoice_code.trim().toUpperCase(),\n        invoice_date:draft.invoice_date,\n        due_date:draft.due_date,\n        pricing_mode:draft.pricing_mode,\n        item_label:draft.item_label.trim(),\n        quantity,\n        unit_price:Math.trunc(draft.unit_price),\n        subtotal,\n        additional_amount:Math.trunc(draft.additional_amount),\n        total_amount:total,\n        total_sessions:totalSessions,\n        total_minutes:totalMinutes,\n        session_start:draft.sessions.map(s=>s.session_date).sort()[0] || null,\n        session_end:draft.sessions.map(s=>s.session_date).sort().at(-1) || null,\n        notes:draft.notes.trim() || null,\n        payment_method_ids:(setup?.payment_methods ?? []).filter(m=>m.is_active !== false).map(m=>m.id).filter(Boolean),\n        sessions:draft.sessions.map((s,index)=>({...s,sort_order:index})),\n      });\n      setMessage('Draft invoice tersimpan.');\n      setDraft(current=>({...current,id}));\n      await load();\n    } catch (error) {\n      console.error('KOJAC save invoice failed',error);\n      setMessage(error instanceof Error ? error.message : 'Draft belum dapat disimpan.');\n    } finally { setBusy(false); }\n  }\n\n  async function issue(row: InvoiceRow) {\n    if (!confirm('Terbitkan invoice ini? Nomor invoice akan menjadi permanen.')) return;\n    setBusy(true);\n    try { await issueManagementInvoice(row.id); setMessage('Invoice berhasil diterbitkan.'); await load(); }\n    catch(error){ console.error(error); setMessage('Invoice belum dapat diterbitkan.'); }\n    finally{ setBusy(false); }\n  }\n\n  async function payment(row: InvoiceRow) {\n    const outstanding=Math.max(0,row.total_amount-row.paid_amount);\n    const amountText=prompt('Nominal pembayaran',String(outstanding));\n    if(amountText===null) return;\n    const amount=Number(amountText.replace(/[^\\d]/g,''));\n    if(!Number.isFinite(amount)||amount<=0) return setMessage('Nominal pembayaran tidak valid.');\n    const method=prompt('Metode pembayaran','Bank BSI');\n    if(!method) return;\n    const reference=prompt('Referensi transfer (opsional)','') ?? '';\n    setBusy(true);\n    try {\n      await recordInvoicePayment({invoiceId:row.id,amount,paymentDate:today(),paymentMethod:method,referenceNumber:reference});\n      setMessage('Pembayaran berhasil dicatat.'); await load();\n    } catch(error){ console.error(error); setMessage('Pembayaran belum dapat dicatat.'); }\n    finally{ setBusy(false); }\n  }\n\n  async function voidInvoice(row: InvoiceRow) {\n    const reason=prompt('Alasan pembatalan invoice');\n    if(!reason?.trim()) return;\n    if(!confirm('Batalkan invoice ini? Tindakan ini akan tercatat pada audit trail.')) return;\n    setBusy(true);\n    try { await voidManagementInvoice(row.id,reason); setMessage('Invoice dibatalkan.'); await load(); }\n    catch(error){ console.error(error); setMessage('Invoice belum dapat dibatalkan.'); }\n    finally{ setBusy(false); }\n  }\n\n  const summary=overview?.summary ?? {total_invoices:0,total_amount:0,paid_amount:0,outstanding_amount:0,overdue_count:0};\n\n  return <div className=\"page invoice-page\">\n    <header className=\"invoice-header\">\n      <div><p className=\"eyebrow\">MANAJEMEN KOJAC</p><h1>Invoice Pembayaran</h1><p>Kelola tagihan siswa/lembaga, pembayaran, dan PDF invoice resmi.</p></div>\n      <button className=\"invoice-btn primary\" onClick={openNew}><FilePlus2 size={16}/> Buat Invoice</button>\n    </header>\n\n    <section className=\"invoice-detail-grid management\">\n      <article className=\"invoice-card\"><span>Invoice</span><strong>{summary.total_invoices}</strong></article>\n      <article className=\"invoice-card\"><span>Total Tagihan</span><strong>{rupiah(summary.total_amount)}</strong></article>\n      <article className=\"invoice-card\"><span>Terbayar</span><strong>{rupiah(summary.paid_amount)}</strong></article>\n      <article className=\"invoice-card\"><span>Sisa</span><strong>{rupiah(summary.outstanding_amount)}</strong></article>\n      <article className=\"invoice-card\"><span>Jatuh Tempo</span><strong>{summary.overdue_count}</strong></article>\n    </section>\n\n    <section className=\"invoice-toolbar\">\n      <label><span>Bulan</span><input type=\"month\" value={month.slice(0,7)} onChange={e=>setMonth(e.target.value+'-01')}/></label>\n      <label className=\"invoice-search\"><Search size={15}/><input placeholder=\"Cari invoice / penerima / kelas\" value={search} onChange={e=>setSearch(e.target.value)}/></label>\n      <button className=\"invoice-btn secondary\" onClick={()=>void load()} disabled={loading}><RefreshCw size={15}/> Refresh</button>\n    </section>\n\n    {message && <div className=\"invoice-notice\">{message}</div>}\n\n    <section className=\"invoice-list\">\n      {loading ? <div className=\"invoice-state\">Memuat invoice…</div> :\n       rows.length===0 ? <div className=\"invoice-state\"><FileText size={30}/><strong>Belum ada invoice pada periode ini.</strong></div> :\n       rows.map(row=><article key={row.id} className=\"invoice-list-row management\">\n         <button className=\"invoice-row-main\" onClick={()=>navigate('/invoice/'+row.id)}>\n           <div><strong>{row.invoice_number||'Draft Invoice'}</strong><span>{row.recipient_name} · {row.class_name_snapshot||row.item_label}</span></div>\n           <div><span>Jatuh tempo</span><strong>{dateId(row.due_date)}</strong></div>\n           <div><span>Total</span><strong>{rupiah(row.total_amount)}</strong></div>\n           <div><span className={\"invoice-status is-\"+row.status}>{statusLabel(row.status)}</span></div>\n         </button>\n         <div className=\"invoice-row-actions\">\n           {row.status==='draft' && <button disabled={busy} onClick={()=>void issue(row)}><CheckCircle2 size={14}/> Terbitkan</button>}\n           {!['draft','paid','void'].includes(row.status) && <button disabled={busy} onClick={()=>void payment(row)}><CircleDollarSign size={14}/> Bayar</button>}\n           {!['paid','void'].includes(row.status) && <button disabled={busy} className=\"danger\" onClick={()=>void voidInvoice(row)}><Ban size={14}/> Void</button>}\n         </div>\n       </article>)}\n    </section>\n\n    {formOpen && <div className=\"invoice-modal-backdrop\" role=\"presentation\" onMouseDown={e=>{if(e.currentTarget===e.target)setFormOpen(false)}}>\n      <section className=\"invoice-modal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Buat Invoice\">\n        <header><div><p className=\"eyebrow\">DRAFT INVOICE</p><h2>Buat / Edit Invoice</h2></div><button onClick={()=>setFormOpen(false)}>×</button></header>\n        <div className=\"invoice-form-grid\">\n          <label><span>Penerima</span><select value={draft.recipient_kind} onChange={e=>setDraft(c=>({...c,recipient_kind:e.target.value as RecipientKind}))}><option value=\"student\">Siswa</option><option value=\"organization\">Lembaga</option></select></label>\n          {draft.recipient_kind==='student' && <label><span>Pilih Siswa</span><select value={draft.recipient_user_id} onChange={e=>selectStudent(e.target.value)}><option value=\"\">Pilih siswa</option>{(setup?.students??[]).map(s=><option key={s.user_id} value={s.user_id}>{s.name}</option>)}</select></label>}\n          <label><span>Nama Penerima</span><input value={draft.recipient_name} onChange={e=>setDraft(c=>({...c,recipient_name:e.target.value}))}/></label>\n          <label><span>No. HP</span><input value={draft.recipient_phone} onChange={e=>setDraft(c=>({...c,recipient_phone:e.target.value}))}/></label>\n          <label className=\"wide\"><span>Alamat</span><textarea value={draft.recipient_address} onChange={e=>setDraft(c=>({...c,recipient_address:e.target.value}))}/></label>\n          <label><span>Kelas</span><select value={draft.class_id} onChange={e=>selectClass(e.target.value)}><option value=\"\">Tanpa kelas</option>{(setup?.classes??[]).map(c=><option key={c.id} value={c.id}>{c.name}{c.code?' · '+c.code:''}</option>)}</select></label>\n          <label><span>Kode Invoice</span><input value={draft.invoice_code} onChange={e=>setDraft(c=>({...c,invoice_code:e.target.value.toUpperCase().replace(/[^A-Z0-9]/g,'')}))}/></label>\n          <label><span>Tanggal Invoice</span><input type=\"date\" value={draft.invoice_date} onChange={e=>setDraft(c=>({...c,invoice_date:e.target.value}))}/></label>\n          <label><span>Jatuh Tempo</span><input type=\"date\" value={draft.due_date} onChange={e=>setDraft(c=>({...c,due_date:e.target.value}))}/></label>\n          <label><span>Mode Tarif</span><select value={draft.pricing_mode} onChange={e=>setDraft(c=>({...c,pricing_mode:e.target.value as PricingMode,invoice_code:e.target.value==='hourly'?'JPNPRIVAT':'JPNSSW'}))}><option value=\"hourly\">Per Jam</option><option value=\"per_student\">Per Siswa</option></select></label>\n          <label><span>Deskripsi</span><input value={draft.item_label} onChange={e=>setDraft(c=>({...c,item_label:e.target.value}))}/></label>\n          {draft.pricing_mode==='per_student' && <label><span>Jumlah Siswa</span><input type=\"number\" min=\"1\" value={draft.quantity} onChange={e=>setDraft(c=>({...c,quantity:Number(e.target.value)}))}/></label>}\n          <label><span>{draft.pricing_mode==='hourly'?'Biaya / Jam':'Biaya / Siswa'}</span><input type=\"number\" min=\"0\" value={draft.unit_price} onChange={e=>setDraft(c=>({...c,unit_price:Number(e.target.value)}))}/></label>\n          <label><span>Tambahan / Lain-lain</span><input type=\"number\" value={draft.additional_amount} onChange={e=>setDraft(c=>({...c,additional_amount:Number(e.target.value)}))}/></label>\n          <label className=\"wide\"><span>Catatan</span><textarea value={draft.notes} onChange={e=>setDraft(c=>({...c,notes:e.target.value}))}/></label>\n        </div>\n\n        <div className=\"invoice-session-editor\">\n          <div className=\"invoice-section-title\"><div><p className=\"eyebrow\">REKAP SESI</p><h3>Halaman 2</h3></div><button onClick={()=>setDraft(c=>({...c,sessions:[...c.sessions,emptySession()]}))}>+ Tambah Sesi</button></div>\n          {draft.sessions.map((session,index)=><div className=\"invoice-session-row\" key={index}>\n            <input type=\"date\" value={session.session_date} onChange={e=>updateSession(index,{session_date:e.target.value})}/>\n            <input type=\"time\" value={session.starts_at.slice(0,5)} onChange={e=>updateSession(index,{starts_at:e.target.value})}/>\n            <input type=\"time\" value={session.ends_at.slice(0,5)} onChange={e=>updateSession(index,{ends_at:e.target.value})}/>\n            <strong>{session.duration_minutes} menit</strong>\n            <button onClick={()=>setDraft(c=>({...c,sessions:c.sessions.filter((_,i)=>i!==index)}))} disabled={draft.sessions.length<=1}>Hapus</button>\n          </div>)}\n        </div>\n\n        <div className=\"invoice-form-summary\">\n          <div><span>Sesi</span><strong>{totalSessions}</strong></div>\n          <div><span>Total Jam</span><strong>{(totalMinutes/60).toFixed(2)}</strong></div>\n          <div><span>Subtotal</span><strong>{rupiah(subtotal)}</strong></div>\n          <div><span>Total</span><strong>{rupiah(total)}</strong></div>\n        </div>\n\n        <footer><button className=\"invoice-btn secondary\" onClick={()=>setFormOpen(false)}>Tutup</button><button className=\"invoice-btn primary\" disabled={busy} onClick={()=>void saveDraft()}><Save size={15}/> {busy?'Menyimpan…':'Simpan Draft'}</button></footer>\n      </section>\n    </div>}\n  </div>;\n}\n";

const css = "\n.invoice-page{max-width:1220px;margin:0 auto;padding-bottom:54px}\n.invoice-header{display:flex;justify-content:space-between;gap:22px;align-items:flex-start;margin-bottom:22px}\n.invoice-header h1{margin:4px 0 7px;font-size:clamp(28px,3vw,38px);letter-spacing:-.035em}\n.invoice-header p{margin:0;color:#806f73}\n.invoice-header-actions{display:flex;gap:8px;flex-wrap:wrap}\n.invoice-btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:39px;padding:9px 13px;border-radius:10px;border:1px solid #dacbd0;font-size:10px;font-weight:800;text-decoration:none;cursor:pointer}\n.invoice-btn.primary{background:#741e31;border-color:#741e31;color:#fff}\n.invoice-btn.secondary{background:#fff;color:#624f54}\n.invoice-btn:disabled{opacity:.55;cursor:not-allowed}\n.invoice-detail-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:16px}\n.invoice-detail-grid.management{grid-template-columns:repeat(5,minmax(0,1fr))}\n.invoice-card{display:grid;gap:5px;padding:14px;border:1px solid #eadfe2;border-radius:13px;background:#fff;box-shadow:0 8px 24px rgba(54,20,28,.035)}\n.invoice-card>span{font-size:9px;color:#8a777c;text-transform:uppercase;letter-spacing:.07em}\n.invoice-card>strong{font-size:15px}\n.invoice-card.wide{grid-column:span 2}\n.invoice-status{display:inline-flex;width:max-content;padding:5px 8px;border-radius:999px;background:#f3ecee;color:#694f55;font-size:9px;font-weight:850}\n.invoice-status.is-issued{background:#edf3ff;color:#315d9b}\n.invoice-status.is-partial{background:#fff5df;color:#a06b0e}\n.invoice-status.is-paid{background:#eaf7ef;color:#28714c}\n.invoice-status.is-void{background:#f4f1f2;color:#83767a;text-decoration:line-through}\n.invoice-panel{margin-top:14px;padding:18px;border:1px solid #eadfe2;border-radius:15px;background:#fff}\n.invoice-section-title{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:13px}\n.invoice-section-title h2,.invoice-section-title h3{margin:2px 0 0}\n.invoice-info-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}\n.invoice-info-grid>div{display:grid;gap:4px;padding:12px;background:#fbf8f9;border-radius:10px}\n.invoice-info-grid span{font-size:8px;color:#8a777c;text-transform:uppercase}\n.invoice-info-grid strong{font-size:11px}\n.invoice-info-grid small{font-size:9px;color:#78686c;line-height:1.45}\n.invoice-note{margin-top:10px;padding:12px;border-left:3px solid #741e31;background:#faf6f7}\n.invoice-note p{margin:5px 0 0;font-size:10px;line-height:1.55}\n.invoice-table-wrap{overflow:auto}\n.invoice-table{width:100%;border-collapse:collapse;min-width:560px}\n.invoice-table th{padding:9px;background:#741e31;color:#fff;text-align:left;font-size:9px}\n.invoice-table td{padding:10px;border-bottom:1px solid #eee4e6;font-size:10px}\n.invoice-payment-list{display:grid;gap:7px}\n.invoice-payment-list article{display:flex;justify-content:space-between;gap:18px;padding:11px;border:1px solid #eee4e6;border-radius:10px}\n.invoice-payment-list article>div{display:grid;gap:3px}\n.invoice-payment-list span,.invoice-payment-list small{font-size:9px;color:#806f73}\n.invoice-empty{padding:20px;text-align:center;color:#8a777c;font-size:10px}\n.invoice-toolbar{display:flex;gap:10px;align-items:end;flex-wrap:wrap;padding:13px;margin-bottom:12px;border:1px solid #eadfe2;border-radius:13px;background:#fff}\n.invoice-toolbar label{display:grid;gap:5px}\n.invoice-toolbar label>span{font-size:8px;text-transform:uppercase;color:#8a777c}\n.invoice-toolbar input,.invoice-toolbar select{min-height:38px;border:1px solid #dbcdd1;border-radius:9px;padding:8px 10px;font:inherit}\n.invoice-search{position:relative;flex:1;min-width:240px}\n.invoice-search svg{position:absolute;left:10px;bottom:11px;color:#8d7a7f}\n.invoice-search input{width:100%;padding-left:33px}\n.invoice-notice{margin:10px 0;padding:10px 12px;border-radius:9px;background:#f8eff1;color:#6f2232;font-size:10px}\n.invoice-list{display:grid;gap:8px}\n.invoice-list-row{display:grid;grid-template-columns:1.6fr .8fr .8fr .55fr;gap:12px;align-items:center;padding:13px 14px;border:1px solid #eadfe2;border-radius:12px;background:#fff;color:inherit;text-decoration:none;box-shadow:0 7px 20px rgba(54,20,28,.025)}\n.invoice-list-row>div{display:grid;gap:3px}\n.invoice-list-row span{font-size:9px;color:#806f73}\n.invoice-list-row strong{font-size:10px}\n.invoice-list-row.management{display:block;padding:0}\n.invoice-row-main{width:100%;display:grid;grid-template-columns:1.6fr .8fr .8fr .55fr;gap:12px;align-items:center;padding:13px 14px;border:0;background:transparent;text-align:left;cursor:pointer}\n.invoice-row-main>div{display:grid;gap:3px}\n.invoice-row-main span{font-size:9px;color:#806f73}\n.invoice-row-main strong{font-size:10px}\n.invoice-row-actions{display:flex;gap:6px;justify-content:flex-end;padding:0 12px 11px}\n.invoice-row-actions button{display:inline-flex;gap:5px;align-items:center;border:1px solid #dacbd0;background:#fff;color:#624f54;padding:6px 8px;border-radius:8px;font-size:9px;font-weight:750;cursor:pointer}\n.invoice-row-actions button.danger{color:#9b2b3d}\n.invoice-state{min-height:180px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;text-align:center;color:#806f73;border:1px dashed #dccfd3;border-radius:13px;background:#fff;font-size:10px}\n.invoice-state button{display:inline-flex;align-items:center;gap:6px;border:1px solid #dacbd0;border-radius:8px;padding:8px 10px;background:#fff}\n.invoice-modal-backdrop{position:fixed;inset:0;z-index:1500;background:rgba(34,19,23,.38);display:flex;justify-content:center;align-items:flex-start;padding:24px;overflow:auto}\n.invoice-modal{width:min(980px,100%);background:#fff;border-radius:16px;box-shadow:0 28px 80px rgba(30,11,16,.26);padding:18px}\n.invoice-modal>header,.invoice-modal>footer{display:flex;justify-content:space-between;gap:12px;align-items:center}\n.invoice-modal>header{padding-bottom:13px;border-bottom:1px solid #eee4e6}\n.invoice-modal>header h2{margin:2px 0}\n.invoice-modal>header>button{border:0;background:transparent;font-size:24px;cursor:pointer}\n.invoice-modal>footer{padding-top:14px;border-top:1px solid #eee4e6;margin-top:15px;justify-content:flex-end}\n.invoice-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;padding:15px 0}\n.invoice-form-grid label{display:grid;gap:5px}\n.invoice-form-grid label.wide{grid-column:1/-1}\n.invoice-form-grid span{font-size:9px;font-weight:750;color:#705d62}\n.invoice-form-grid input,.invoice-form-grid select,.invoice-form-grid textarea{width:100%;min-height:39px;padding:9px 10px;border:1px solid #d9cbd0;border-radius:9px;font:inherit}\n.invoice-form-grid textarea{min-height:70px;resize:vertical}\n.invoice-session-editor{padding:13px;border:1px solid #eadfe2;border-radius:12px;background:#fcfafa}\n.invoice-session-editor .invoice-section-title button{border:1px solid #dacbd0;background:#fff;border-radius:8px;padding:7px 9px;font-size:9px;font-weight:750}\n.invoice-session-row{display:grid;grid-template-columns:1.2fr .8fr .8fr .7fr .55fr;gap:7px;align-items:center;margin-top:7px}\n.invoice-session-row input{min-height:36px;border:1px solid #ddcfd3;border-radius:8px;padding:7px}\n.invoice-session-row strong{font-size:9px}\n.invoice-session-row button{border:0;background:#f7edef;color:#8b2a3d;border-radius:7px;padding:8px;font-size:8px}\n.invoice-form-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:11px}\n.invoice-form-summary>div{display:grid;gap:3px;padding:10px;background:#faf6f7;border-radius:9px}\n.invoice-form-summary span{font-size:8px;color:#877478}\n.invoice-form-summary strong{font-size:11px}\n@media(max-width:850px){\n  .invoice-header{flex-direction:column}\n  .invoice-detail-grid,.invoice-detail-grid.management,.invoice-info-grid{grid-template-columns:1fr 1fr}\n  .invoice-list-row,.invoice-row-main{grid-template-columns:1fr 1fr}\n  .invoice-form-grid{grid-template-columns:1fr}\n  .invoice-form-grid label.wide{grid-column:auto}\n  .invoice-session-row{grid-template-columns:1fr 1fr}\n  .invoice-form-summary{grid-template-columns:1fr 1fr}\n}\n@media(max-width:520px){\n  .invoice-detail-grid,.invoice-detail-grid.management,.invoice-info-grid{grid-template-columns:1fr}\n  .invoice-card.wide{grid-column:auto}\n  .invoice-list-row,.invoice-row-main{grid-template-columns:1fr}\n  .invoice-modal-backdrop{padding:0}\n  .invoice-modal{border-radius:0;min-height:100vh}\n  .invoice-session-row{grid-template-columns:1fr}\n}\n";

